INSERT INTO site_content (key, value, updated_at) VALUES
('legacyThreads', '[{"id":"atmospheric-dynamics","title":"Atmospheric dynamics","text":"Planetary waves, circulation, radiation, and the physics that set atmospheres in motion."},{"id":"climate-change","title":"Climate change","text":"Physical understanding of radiative forcing, greenhouse warming, climate sensitivity, and feedbacks."},{"id":"climate-modeling","title":"Climate modeling","text":"Models used not merely to predict, but to reveal how interacting processes create climate."},{"id":"land-atmosphere","title":"Land–atmosphere interactions","text":"Vegetation, soils, water, snow, roots, and surface energy made active parts of the climate system."},{"id":"observation-space","title":"Observation from space","text":"Remote sensing used to confront models with the changing temperature and condition of land."},{"id":"coupled-earth","title":"A coupled Earth","text":"Water, energy, carbon, ecosystems, and human influence brought into one scientific picture."}]', datetime('now')),
('homeLegacyCards', '[{"title":"He opened new frontiers in planetary-atmosphere science","text":"Robert advanced the theory of planetary waves and developed pioneering global models of upper-atmospheric dynamics and radiation, extending from Earth’s stratosphere and thermosphere to the atmospheres of Venus and Mars.","threadIds":["atmospheric-dynamics","climate-modeling"]},{"title":"He established a quantitative foundation for understanding global warming","text":"Robert’s seminal work on radiative forcing, climate sensitivity, and greenhouse gases helped establish how changes in Earth’s energy balance translate into global temperature change, a foundation for modern assessments of greenhouse warming and global change.","threadIds":["climate-change","atmospheric-dynamics","climate-modeling"]},{"title":"He pioneered integration of land processes into global climate models","text":"Robert transformed the land process from a passive boundary into an active, interacting component of global climate models. He connected atmosphere, biosphere, and hydrosphere into a fuller and faithful picture of the Earth system.","threadIds":["land-atmosphere","climate-modeling","observation-space","coupled-earth"]},{"title":"He inspired generations of scientists","text":"Robert passed on more than knowledge. His rigor, curiosity, breadth of vision, and generosity live on through generations of students, postdocs, collaborators, and scientific communities.","threadIds":["atmospheric-dynamics","climate-change","climate-modeling","land-atmosphere","observation-space","coupled-earth"]}]', datetime('now')),
('secondaryLegacyTopics', '[{"title":"Planetary atmospheres","text":"Global circulation, radiation, and upper-atmosphere modeling for Earth, Venus, and Mars.","threadIds":["atmospheric-dynamics","climate-modeling"]},{"title":"Tropical deforestation","text":"How land-cover change in the Amazon reshapes regional energy, water, and climate.","threadIds":["land-atmosphere","climate-change","coupled-earth"]},{"title":"Regional climate modeling","text":"Early development of regional models for resolving climate processes below the global scale.","threadIds":["climate-modeling","climate-change"]},{"title":"Carbon & nitrogen cycles","text":"Coupling biogeochemistry with water and energy cycles in land and Earth-system models.","threadIds":["land-atmosphere","coupled-earth"]},{"title":"Dynamic vegetation","text":"Representing vegetation change as an active part of climate and Earth-system feedbacks.","threadIds":["land-atmosphere","coupled-earth"]},{"title":"Solar geoengineering","text":"Early analysis of deliberate changes to Earth’s energy balance and their climatic implications.","threadIds":["climate-change","climate-modeling"]},{"title":"Hydrology & drought","text":"Soil moisture, evapotranspiration, groundwater, drought, and land–climate feedbacks.","threadIds":["land-atmosphere","coupled-earth"]},{"title":"Aerosols & radiation","text":"Radiative effects of aerosols, greenhouse gases, and atmospheric composition across climate scales.","threadIds":["atmospheric-dynamics","climate-change"]}]', datetime('now')),
('homeLegacyIntro', 'Rather than a single linear path, Bob’s work formed a connected scientific landscape. Foundational ideas in atmospheric dynamics, climate change, modeling, land–atmosphere exchange, observations from space, and the coupled Earth repeatedly converged as the scale of his questions widened.', datetime('now'))
